    ('mprc_chat_spotify_music_summary', 'Mprc Chat Spotify Music Summary', 'multiline', 'Play', 'Spotify Sense: available\nStory music: MPRC only sends scene intent; Spotify Sense owns playback, device selection, and fades.\nLast request: none yet.\nDefault selection rule: prefer cinematic ambience unless the story beat clearly needs active music.', (), True, False, {}),
    ('unnamed_qlabel_qlabel#25', 'unnamed_qlabel_qlabel#25', 'display', 'Voice', 'Shows the speaker tags and current voice-routing preview for the latest story reply.', (), True, False, {}),
    ('mprc_chat_voice_segments_summary', 'Mprc Chat Voice Segments Summary', 'multiline', 'Voice', "Multi-voice contract: [NARRATOR] carries narration; [CHARACTER: Exact Name] carries only that speaker's spoken line.\nTagged speakers: none in latest reply yet.\nLatest reply: no Play story reply has been produced yet.", (), True, False, {}),
