    ('mprc_chat_visual_beat_summary', 'Mprc Chat Visual Beat Summary', 'multiline', 'Play', 'Latest visible beat: No latest visible action yet.\nVisual subject: Mentor.\nLocation: The Velvet Lantern Hotel, a restored art-deco hideaway above a stormy harbor..\nTime: Rainy midnight.\nMood: Velvet-dark, flirtatious, mysterious, cinematic.\nStory goal: Follow a trail of coded invitations, stolen memories, and dangerous attraction while preserving player choice and a suggestive, non-explicit tone..\nImage intent: No Visual Reply prompt has been generated yet.\nSelection rule: prefer the newest visible scene beat; ignore choices, hidden prompt text, and stale setup.', (), True, False, {}),
    ('unnamed_qlabel_qlabel#27', 'unnamed_qlabel_qlabel#27', 'display', 'Play', 'Shows addon-local memory, configured story archives, and data-bank indexing state.', (), True, False, {}),
    ('mprc_chat_memory_databank_summary', 'Mprc Chat Memory Databank Summary', 'multiline', 'Play', 'Database backend: SQLite (available).\nData bank: available.\nPinned facts: 0.\nRemembered story events: 0.\nChapter summaries: 0.\nCharacter memory entries: 0.\nConfigured data-bank sources: none configured.\nIndexed data-bank sources: none indexed yet.\nPrompt use: relevant memory and data-bank snippets are read into hidden MPRC story context; this card does not change memory.', (), True, False, {}),
